"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { CurrencyAmount } from "@uniswap/sdk-core";
import { LP_INCENTIVES_REWARD_TOKEN } from "components/LpIncentives/constants";
import JSBI from "jsbi";
import { useMemo } from "react";
import { FeatureFlags } from "uniswap/src/features/gating/flags";
import { useFeatureFlag } from "uniswap/src/features/gating/hooks";
import { useLocalizationContext } from "uniswap/src/features/language/LocalizationContext";
import { useUSDCPrice } from "uniswap/src/features/transactions/hooks/useUSDCPrice";
import { NumberType } from "utilities/src/format/types";
export function useLpIncentivesFormattedEarnings({
  liquidityPosition,
  fiatFeeValue0,
  fiatFeeValue1
}) {
  const { formatCurrencyAmount } = useLocalizationContext();
  const isLPIncentivesEnabled = useFeatureFlag(FeatureFlags.LpIncentives);
  const { price: uniPrice } = useUSDCPrice(LP_INCENTIVES_REWARD_TOKEN);
  return useMemo(() => {
    const formatCurrency = (value) => {
      return formatCurrencyAmount({
        value,
        type: NumberType.FiatStandard
      });
    };
    const result = {
      uniLpRewardsCurrencyAmount: void 0,
      uniLpRewardsFiatValue: void 0,
      totalFeesFiatValue: void 0,
      formattedFeesValue: void 0,
      formattedRewardsValue: void 0,
      hasRewards: false,
      hasFees: false,
      totalEarningsFiatValue: void 0,
      totalFormattedEarnings: void 0
    };
    const hasValidFiat0 = fiatFeeValue0 && fiatFeeValue0.greaterThan(0);
    const hasValidFiat1 = fiatFeeValue1 && fiatFeeValue1.greaterThan(0);
    if (hasValidFiat0 && hasValidFiat1) {
      result.totalFeesFiatValue = fiatFeeValue0.add(fiatFeeValue1);
      result.formattedFeesValue = formatCurrency(result.totalFeesFiatValue);
      result.hasFees = result.totalFeesFiatValue.greaterThan(0);
    } else if (hasValidFiat0) {
      result.totalFeesFiatValue = fiatFeeValue0;
      result.formattedFeesValue = formatCurrency(result.totalFeesFiatValue);
      result.hasFees = result.totalFeesFiatValue.greaterThan(0);
    } else if (hasValidFiat1) {
      result.totalFeesFiatValue = fiatFeeValue1;
      result.formattedFeesValue = formatCurrency(result.totalFeesFiatValue);
      result.hasFees = result.totalFeesFiatValue.greaterThan(0);
    } else {
      const hasToken0Fees = liquidityPosition.token0UncollectedFees && liquidityPosition.token0UncollectedFees !== "0";
      const hasToken1Fees = liquidityPosition.token1UncollectedFees && liquidityPosition.token1UncollectedFees !== "0";
      if (hasToken0Fees || hasToken1Fees) {
        try {
          const token0Amount = hasToken0Fees ? CurrencyAmount.fromRawAmount(liquidityPosition.currency0Amount.currency, liquidityPosition.token0UncollectedFees) : void 0;
          const token1Amount = hasToken1Fees ? CurrencyAmount.fromRawAmount(liquidityPosition.currency1Amount.currency, liquidityPosition.token1UncollectedFees) : void 0;
          const mockUSDCToken = liquidityPosition.currency0Amount.currency;
          let totalUSDAmount = CurrencyAmount.fromRawAmount(mockUSDCToken, 0);
          if (token0Amount && !token0Amount.equalTo(0)) {
            totalUSDAmount = totalUSDAmount.add(CurrencyAmount.fromRawAmount(mockUSDCToken, token0Amount.quotient));
          }
          if (token1Amount && !token1Amount.equalTo(0)) {
            const token0Decimals = liquidityPosition.currency0Amount.currency.decimals;
            const token1Decimals = liquidityPosition.currency1Amount.currency.decimals;
            const decimalDiff = token0Decimals - token1Decimals;
            let scaledToken1Quotient = token1Amount.quotient;
            if (decimalDiff > 0) {
              scaledToken1Quotient = JSBI.multiply(
                scaledToken1Quotient,
                JSBI.exponentiate(JSBI.BigInt(10), JSBI.BigInt(decimalDiff))
              );
            } else if (decimalDiff < 0) {
              scaledToken1Quotient = JSBI.divide(
                scaledToken1Quotient,
                JSBI.exponentiate(JSBI.BigInt(10), JSBI.BigInt(-decimalDiff))
              );
            }
            totalUSDAmount = totalUSDAmount.add(CurrencyAmount.fromRawAmount(mockUSDCToken, scaledToken1Quotient));
          }
          if (!totalUSDAmount.equalTo(0)) {
            result.totalFeesFiatValue = totalUSDAmount;
            result.formattedFeesValue = formatCurrency(totalUSDAmount);
            result.hasFees = true;
          }
        } catch (error) {
          console.warn("Failed to create fallback USD values for fees:", error);
        }
      }
    }
    const shouldIncludeRewards = liquidityPosition.version === ProtocolVersion.V4 && liquidityPosition.unclaimedRewardsAmountUni && liquidityPosition.unclaimedRewardsAmountUni !== "0" && isLPIncentivesEnabled;
    result.totalEarningsFiatValue = result.totalFeesFiatValue;
    result.totalFormattedEarnings = result.formattedFeesValue;
    if (!shouldIncludeRewards) {
      return result;
    }
    const uniLpRewardsCurrencyAmount = CurrencyAmount.fromRawAmount(
      LP_INCENTIVES_REWARD_TOKEN,
      liquidityPosition.unclaimedRewardsAmountUni
    );
    result.uniLpRewardsCurrencyAmount = uniLpRewardsCurrencyAmount;
    result.hasRewards = uniLpRewardsCurrencyAmount.greaterThan(0);
    const uniLpRewardsFiatValue = uniPrice ? uniPrice.quote(uniLpRewardsCurrencyAmount) : void 0;
    result.uniLpRewardsFiatValue = uniLpRewardsFiatValue;
    if (uniLpRewardsFiatValue) {
      result.formattedRewardsValue = formatCurrency(uniLpRewardsFiatValue);
      result.totalEarningsFiatValue = CurrencyAmount.fromRawAmount(
        uniLpRewardsFiatValue.currency,
        result.totalFeesFiatValue ? JSBI.add(result.totalFeesFiatValue.quotient, uniLpRewardsFiatValue.quotient) : uniLpRewardsFiatValue.quotient
      );
      result.totalFormattedEarnings = formatCurrency(result.totalEarningsFiatValue);
    }
    return result;
  }, [fiatFeeValue0, fiatFeeValue1, liquidityPosition, isLPIncentivesEnabled, uniPrice, formatCurrencyAmount]);
}
